WITH qualified AS (
  SELECT order_id, customer_id, ordered_at, order_total
  FROM main.orders
  WHERE order_total > 0
),
ranked AS (
  SELECT customer_id, ordered_at,
         ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY ordered_at) AS rn
  FROM qualified
)
SELECT AVG(diff_days) AS avg_days_between_first_and_second
FROM (
  SELECT (CAST(second.ordered_at AS DATE) - CAST(first.ordered_at AS DATE)) AS diff_days
  FROM (
    SELECT customer_id, ordered_at FROM ranked WHERE rn = 1
  ) first
  JOIN (
    SELECT customer_id, ordered_at FROM ranked WHERE rn = 2
  ) second USING (customer_id)
) sub;

SELECT SUM(oi.supply_cost) AS total_perishable_supply_spend
FROM main.order_items oi
WHERE EXISTS (
    SELECT 1 FROM main.supplies s
    WHERE s.product_id = oi.product_id AND s.is_perishable_supply = true
);
